import pathlib, pymupdf, collections, sys
d = pathlib.Path("/home/claude/work/Content_extracted/Content")
for f in sorted(d.glob("*.pdf")):
    doc = pymupdf.open(f)
    pua = collections.Counter(); fonts = collections.Counter(); total = 0
    for page in doc:
        for b in page.get_text("dict")["blocks"]:
            for l in b.get("lines", []):
                for s in l["spans"]:
                    for ch in s["text"]:
