import pymupdf, collections, pathlib, json
files = ["2112.01486v1.pdf", "Wooldridge_u20.pdf",
         "A Simple Transformation Approach to Difference-in-Differences Estimation for Panel Data.pdf",
         "Joshi-CorrelatedRandomEffects-2019.pdf", "ssrn-5325686.pdf"]
d = pathlib.Path("/home/claude/work/Content_extracted/Content")
inv = collections.Counter()
for fn in files:
    doc = pymupdf.open(d/fn)
    for page in doc:
        for b in page.get_text("dict")["blocks"]:
            for l in b.get("lines", []):
                for s in l["spans"]:
                    for ch in s["text"]:
                        if 0xE000 <= ord(ch) <= 0xF8FF:
                            inv[(s["font"].split("+")[-1], ord(ch))] += 1
print("distinct (font, code) pairs:", len(inv))
byfont = collections.defaultdict(list)
for (f, c), n in inv.items(): byfont[f].append((c, n))
for f, items in sorted(byfont.items()):
    items.sort()
    print(f"\n{f} ({len(items)} distinct, {sum(n for _,n in items)} occurrences)")
    print("  " + " ".join(f"{c:04X}x{n}" for c, n in items))
json.dump({f"{f}|{c:04X}": n for (f, c), n in inv.items()}, open("pua_inventory.json","w"), indent=0)
