import pymupdf, pathlib, re, collections
d = pathlib.Path('/home/claude/work/Content_extracted/Content')
def parse_cmap(s):
    m = {}
    for blk in re.findall(rb'beginbfchar(.*?)endbfchar', s, re.S):
        for src, dst in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
            m[int(src,16)] = int(dst,16)
    for blk in re.findall(rb'beginbfrange(.*?)endbfrange', s, re.S):
        for lo, hi, dst in re.findall(rb'<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>', blk):
            lo,hi,dst = int(lo,16), int(hi,16), int(dst,16)
            for i in range(hi-lo+1): m[lo+i] = dst+i
    return m
anchors = collections.defaultdict(dict)
offsets = collections.Counter()
for fn in ['2112.01486v1.pdf','Wooldridge_u20.pdf']:
    doc = pymupdf.open(d/fn); seen=set()
    for p in range(len(doc)):
        for f in doc.get_page_fonts(p, full=True):
            short = f[3].split('+')[-1]
            if not short.startswith('Tci') or (fn,short) in seen: continue
            seen.add((fn,short))
            tu = doc.xref_get_key(f[0], "ToUnicode")
            if tu[0] != 'xref': continue
            cm = parse_cmap(doc.xref_stream(int(tu[1].split()[0])))
            for gid, uni in sorted(cm.items()):
                if 0xE000 <= uni <= 0xF8FF:
                    offsets[uni - 0xF000 - gid] += 1
                else:
                    anchors[short][gid] = uni
    doc.close()
print("PUA-lowbyte minus GID, distribution:", dict(offsets))
print("\nREAL-UNICODE ANCHORS (producer knew these glyphs):")
for font, a in sorted(anchors.items()):
    print(f"  {font}:")
    for gid, uni in sorted(a.items()):
        code = gid + 0x21
