"""Extract markdown from a born-digital PDF using pdfminer.six.

pymupdf4llm was the obvious tool and it silently drops display equations -- the
line is present in the text layer and simply does not reach the markdown. For a
corpus of econometrics papers that is disqualifying, so extraction runs through
pdfminer.six's layout analysis instead, with the private-use glyph repair applied
at the character level where the font name is still available.
"""

import re
import statistics
from collections import Counter

from pdfminer.high_level import extract_pages
from pdfminer.layout import LAParams, LTAnno, LTChar, LTTextContainer, LTTextLine

import pua_repair

LA = LAParams(line_margin=0.45, char_margin=2.2, word_margin=0.1, boxes_flow=0.5,
              detect_vertical=False, all_texts=False)

# Lines that are pure furniture.
PAGENUM = re.compile(r"^\s*[-–—]?\s*(?:\d{1,4}|[ivxlcdm]{1,7})\s*[-–—]?\s*$", re.I)
JSTOR = re.compile(r"JSTOR is a not-for-profit|Terms and Conditions of Use|"
                   r"digitize, preserve and extend access|This content downloaded from",
                   re.I)
SECNUM = re.compile(r"^\s*(\d{1,2}(?:\.\d{1,2}){0,2})\.?\s+([A-Z][^.]{2,90})\s*$")
APPENDIX = re.compile(r"^\s*(Appendix\s+[A-Z0-9]?|References|Acknowledg(e)?ments?|Abstract|"
                      r"Keywords?|JEL\s+Classification)\s*:?\s*$", re.I)

# Characters that make a line look like mathematics rather than prose.
MATHY = set("=+−-<>≤≥≈≡∈∑∏∫√∞⊗⋅×⋮⋯□()[]{}′|/^_")
GREEK = set("ΓΔΘΛΞΠΣΦΨΩαβγδεζηθικλμνξοπρςστυφχψω")


def _line_text(line: LTTextLine) -> tuple[str, list[float], set[str]]:
    out, sizes, fonts = [], [], set()
    for ch in line:
        if isinstance(ch, LTChar):
            fname = (ch.fontname or "").split("+")[-1]
            out.append(pua_repair.repair_text(ch.get_text(), fname))
            sizes.append(round(ch.size, 1))
            fonts.add(fname)
        elif isinstance(ch, LTAnno):
            out.append(ch.get_text())
    return "".join(out).rstrip("\n"), sizes, fonts


def _is_math(s: str) -> bool:
    t = s.strip()
    if len(t) < 2:
        return False
    words = re.findall(r"[A-Za-z]{4,}", t)
    sym = sum(1 for c in t if c in MATHY or c in GREEK)
    # A display equation has symbols and almost no real words.
    return sym >= 2 and len(words) <= 1 and sym / max(1, len(t)) > 0.10


def _dehyphenate(a: str, b: str) -> str | None:
    if a.endswith("-") and b[:1].islower():
        return a[:-1] + b
    return None


def extract(path: str) -> list[dict]:
    """Return a list of {kind, text} blocks in reading order."""
    pages = []
    for layout in extract_pages(path, laparams=LA):
        blocks = []
        for el in layout:
            if not isinstance(el, LTTextContainer):
                continue
            lines = []
            for ln in el:
                if not isinstance(ln, LTTextLine):
                    continue
                txt, sizes, fonts = _line_text(ln)
                if txt.strip():
                    lines.append({"text": txt, "size": statistics.median(sizes) if sizes else 0.0,
                                  "x0": ln.x0, "fonts": fonts})
            if lines:
                blocks.append({"lines": lines, "x0": el.x0, "y0": el.y0, "y1": el.y1})
        blocks.sort(key=lambda b: -b["y1"])
        pages.append(blocks)

    # Body font size = the most common rounded size across the document.
    sizes = Counter()
    for pg in pages:
        for b in pg:
            for l in b["lines"]:
                sizes[round(l["size"])] += len(l["text"])
    body = sizes.most_common(1)[0][0] if sizes else 10

    # Running heads/feet: short lines that recur on many pages.
    reps = Counter()
    for pg in pages:
        for b in pg[:1] + pg[-1:]:
            for l in b["lines"]:
                t = l["text"].strip()
                if len(t) < 90:
                    reps[re.sub(r"\d+", "#", t)] += 1
    furniture = {k for k, v in reps.items() if v >= max(3, len(pages) * 0.3)}

    out: list[dict] = []
    for pg in pages:
        for b in pg:
            texts = [l["text"] for l in b["lines"]]
            joined_probe = " ".join(texts)
            if JSTOR.search(joined_probe):
                continue
            keep = []
            for l in b["lines"]:
                t = l["text"].strip()
                if not t or PAGENUM.match(t):
                    continue
                if re.sub(r"\d+", "#", t) in furniture:
                    continue
                keep.append(l)
            if not keep:
                continue

            med = statistics.median([l["size"] for l in keep])
            joined = ""
            for l in keep:
                t = l["text"].rstrip()
                if not joined:
                    joined = t
                    continue
                merged = _dehyphenate(joined, t.lstrip())
                joined = merged if merged else joined + " " + t.lstrip()
            joined = re.sub(r"[ \t]{2,}", " ", joined).strip()
            if not joined:
                continue

            m = SECNUM.match(joined)
            if len(keep) <= 2 and (m or APPENDIX.match(joined)) and len(joined) < 100:
                out.append({"kind": "h", "level": 2 if m and "." not in m.group(1) else 3,
                            "text": joined})
                continue
            if len(keep) <= 2 and med >= body + 1.0 and len(joined) < 120:
                out.append({"kind": "h", "level": 2, "text": joined})
                continue
            if all(_is_math(l["text"]) for l in keep) and len(keep) <= 4:
                out.append({"kind": "math", "text": joined})
                continue
            out.append({"kind": "p", "text": joined})
    return out


def to_markdown(path: str) -> str:
    parts = []
    for b in extract(path):
        if b["kind"] == "h":
            parts.append("#" * b["level"] + " " + b["text"])
        elif b["kind"] == "math":
            # Kept verbatim as its own block. These are Unicode, not LaTeX, so
            # wrapping them in $$ would only break rendering.
            parts.append("> " + b["text"])
        else:
            parts.append(b["text"])
    return "\n\n".join(parts) + "\n"

