            m = SECNUM.match(joined)
            if len(keep) <= 2 and (m or APPENDIX.match(joined)) and len(joined) < 100:
                out.append({"kind": "h", "level": 2 if m and "." not in m.group(1) else 3,
                            "text": joined})
                continue
            if len(keep) <= 2 and med >= body + 1.0 and len(joined) < 120:
                out.append({"kind": "h", "level": 2, "text": joined})
                continue
            if all(_is_math(l["text"]) for l in keep) and len(keep) <= 4:
                out.append({"kind": "math", "text": joined})
                continue
            out.append({"kind": "p", "text": joined})
    return out


def to_markdown(path: str) -> str:
    parts = []
    for b in extract(path):
        if b["kind"] == "h":
            parts.append("#" * b["level"] + " " + b["text"])
        elif b["kind"] == "math":
            # Kept verbatim as its own block. These are Unicode, not LaTeX, so
            # wrapping them in $$ would only break rendering.
            parts.append("> " + b["text"])
        else:
            parts.append(b["text"])
    return "\n\n".join(parts) + "\n"

