'''def epub_footnotes(path: pathlib.Path) -> list[str]:
    """Pandoc emits `[^1]:` with no body for these EPUBs -- it sees the note
    reference but cannot resolve the target, and warns 'Reference not found for
    FN0001'. The text is right there in the XHTML, so recover it by id."""
    import zipfile
    notes = []
    with zipfile.ZipFile(path) as z:
        for name in sorted(n for n in z.namelist() if n.lower().endswith((".xhtml", ".html"))):
            soup = BeautifulSoup(z.read(name), "lxml")
            for el in soup.find_all(attrs={"id": re.compile(r"^FN0*\\d+$", re.I)}):
                txt = el.get_text(" ", strip=True)
                if txt:
                    notes.append(re.sub(r"\\s+", " ", txt))
    return notes


def fill_footnotes(md: str, notes: list[str]) -> str:
    if not notes:
        return md
    idx = [0]

    def sub(m):
        i = idx[0]
        idx[0] += 1
        return f"{m.group(1)} {notes[i]}" if i < len(notes) else m.group(0)

    return re.sub(r"^(\\[\\^\\d+\\]:)\\s*$", sub, md, flags=re.M)


def convert(kind: str, path: pathlib.Path) -> str:
    if kind == "epub":
        return tidy(fill_footnotes(pandoc(str(path), "epub"), epub_footnotes(path)))''')
